test('vatSummary with discount and VAT', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = vatSummary([issued]);

  // DEV-HOUR: 10 × 9500 = 95000
  // Discount: 95000 × 10% = 9500
  // Base: 95000 - 9500 = 85500
  const expectedBase = 95000 - 9500;
  assert.equal(result[0].base, expectedBase);

  // VAT: 85500 × 21% = 17955
  const expectedVat = Math.round(expectedBase * 0.21);
  assert.equal(result[0].vat, expectedVat);
});

