test('vatSummary calculates base correctly', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = vatSummary([issued]);

  // DEV-HOUR: 10 × 9500 cents = 95000 cents
  // No discount, no tier discount (C-001 has gold tier which adds 5% discount)
  // Actually, C-001 is gold tier so it gets 5% discount
  // base = 95000 - (95000 × 0.05) = 95000 - 4750 = 90250
